/**
 * Gibt ein handgezeichnetes Icon als Inline-SVG aus. Die Icons sind Flächen,
 * der dritte Parameter (Strichstärke) gilt nur für die Linienicons.
 */
function elfzwo_icon( $name, $class = 'h-4 w-4', $stroke_width = 2 ) {
	$paths = elfzwo_icon_paths();
	if ( ! isset( $paths[ $name ] ) ) {
		return '';
	}
	if ( 'linie' === ( $paths[ $name ][2] ?? '' ) ) {
		return sprintf(
			'<svg class="icon %1$s" viewBox="%2$s" fill="none" stroke="currentColor" stroke-width="%3$s" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">%4$s</svg>',
			esc_attr( $class ),
			esc_attr( $paths[ $name ][0] ),
			esc_attr( $stroke_width ),
			$paths[ $name ][1]
		);
	}
	return sprintf(
		'<svg class="icon %1$s" viewBox="%2$s" fill="currentColor" aria-hidden="true">%3$s</svg>',
		esc_attr( $class ),
		esc_attr( $paths[ $name ][0] ),
		$paths[ $name ][1]
	);
}

function elfzwo_icon_keys() {
	return array_values( array_diff( array_keys( elfzwo_icon_paths() ), array( 'sparkles' ) ) );
}
